{"src/exportCsv.mjs":"/** rows为对象数组，返回可用于下载的字符串。 */
export function exportCsv(rows) {
  const list = Array.isArray(rows) ? rows : [];

  // 收集所有字段名，保持首次出现顺序，避免不同对象字段不一致时丢列。
  const headers = [];
  const seen = new Set();
  for (const row of list) {
    if (row === null || typeof row !== "object") continue;
    for (const key of Object.keys(row)) {
      if (!seen.has(key)) {
        seen.add(key);
        headers.push(key);
      }
    }
  }

  const escapeCell = (value) => {
    let text;
    if (value === null || value === undefined) {
      text = "";
    } else if (value instanceof Date) {
      text = Number.isNaN(value.getTime()) ? "" : value.toISOString();
    } else if (typeof value === "object") {
      try {
        text = JSON.stringify(value);
      } catch {
        text = String(value);
      }
    } else {
      text = String(value);
    }

    // 防公式注入：外部填写内容以 = + - @ 或制表/回车开头时加单引号前缀。
    if (/^[=+\-@\t\r]/.test(text)) {
      text = "'" + text;
    }

    // RFC 4180 转义：含逗号、双引号、换行时用双引号包裹，内部双引号翻倍。
    if (/[",\r\n]/.test(text)) {
      text = '"' + text.replace(/"/g, '""') + '"';
    }
    return text;
  };

  const lines = [];
  lines.push(headers.map(escapeCell).join(","));
  for (const row of list) {
    const source = row !== null && typeof row === "object" ? row : {};
    lines.push(headers.map((key) => escapeCell(source[key])).join(","));
  }

  // 带 BOM，便于 Excel 正确识别 UTF-8；行尾用 CRLF。
  return "\uFEFF" + lines.join("\r\n") + "\r\n";
}
"}
